@'
from collections import defaultdict
from math import isfinite
from pathlib import Path
from statistics import median
import pyarrow.parquet as pq

views = Path(r'D:\Libraries\Documents\projects\opal-work\live\ws\.clio\datasets\76bf90275f7a9839\views')
raw = Path(r'D:\Libraries\Documents\projects\OPAL\67_2026.04.09_OPAL.0002_Weston_PC\67_2026.04.09_OPAL.0002_Weston_PC\rgb2\rgb2-features.parquet')
design = {r['unit_id']: (r['genotype'], r['treatment']) for r in pq.read_table(views / 'design.parquet', columns=['unit_id', 'genotype', 'treatment']).to_pylist()}
bbox_names = ['feature_bbox_row_start_px', 'feature_bbox_row_stop_px', 'feature_bbox_col_start_px', 'feature_bbox_col_stop_px']
roi_names = ['tray_roi_crop_row_start_px', 'tray_roi_crop_row_stop_px', 'tray_roi_crop_col_start_px', 'tray_roi_crop_col_stop_px']
edge = {}
for row in pq.read_table(raw, columns=['sample_key', *bbox_names, *roi_names]).to_pylist():
    b = [row[name] for name in bbox_names]
    r = [row[name] for name in roi_names]
    edge[row['sample_key']] = None if any(v is None for v in b + r) else (b[0] <= r[0] or b[1] >= r[1] or b[2] <= r[2] or b[3] >= r[3])
plant_day = defaultdict(list)
for path in sorted(views.glob('observations_rgb2_features_*.parquet')):
    for row in pq.read_table(path, columns=['unit_id', 'time', 'trait', 'value', 'source_row_key']).to_pylist():
        day = row['time'][:10]
        value = row['value']
        if row['trait'] == 'area_px' and day in ('2026-04-14', '2026-04-27') and value is not None and isfinite(value) and value > 0 and edge.get(row['source_row_key']) is False and row['unit_id'] in design:
            plant_day[(row['unit_id'], day)].append(value)
daily = {key: median(values) for key, values in plant_day.items()}
paired = defaultdict(list)
for unit_id, (genotype, treatment) in design.items():
    start = daily.get((unit_id, '2026-04-14'))
    end = daily.get((unit_id, '2026-04-27'))
    if start is not None and end is not None:
        paired[(genotype, treatment)].append((start, end))
levels = ['0', '50', '100', '200', '500', '1000']
print('Each n is paired plants; area is RGB2 top-view pixels; same-day observations were collapsed to one plant median.')
print('genotype | treatment | n | median_start_px | median_end_px | median_plant_change_px | median_plant_fold')
for genotype in sorted({value[0] for value in design.values()}):
    for level in levels:
        pairs = paired.get((genotype, level), [])
        if pairs:
            print(f'{genotype} | {level} | {len(pairs)} | {median(a for a, b in pairs):.1f} | {median(b for a, b in pairs):.1f} | {median(b-a for a, b in pairs):.1f} | {median(b/a for a, b in pairs):.3f}')
        else:
            print(f'{genotype} | {level} | 0 | NA | NA | NA | NA')
for level in ('500', '1000'):
    comparable = [g for g in {value[0] for value in design.values()} if paired.get((g, '0')) and paired.get((g, level))]
    lower_change = sum(median(b-a for a, b in paired[(g, level)]) < median(b-a for a, b in paired[(g, '0')]) for g in comparable)
    lower_fold = sum(median(b/a for a, b in paired[(g, level)]) < median(b/a for a, b in paired[(g, '0')]) for g in comparable)
    print(f'{level} vs 0: lower median plant change in {lower_change}/{len(comparable)} genotypes; lower median plant fold in {lower_fold}/{len(comparable)} genotypes')
print('paired coverage by treatment:', {level: sum(len(pairs) for (g, t), pairs in paired.items() if t == level) for level in levels})
'@ | uv run --with pyarrow python -

